<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {useProjectStore} from '../stores/project';
import type {AssetUploadMetadata,FileRecord,Release,SourceRights,CreatorCapabilities} from '@loreviva/sdk-ts';
import {schemas} from '../lib/validation';
import SchemaField from '../components/SchemaField.vue';
import {adoptPreset} from '../lib/presets';
import FieldErrors from '../components/FieldErrors.vue';
import PackagePreview from '../components/PackagePreview.vue';
const s=useProjectStore();const error=ref<unknown>();const releases=ref<Release[]>([]);const caps=ref<CreatorCapabilities>();const file=ref<File>();const record=ref<FileRecord>();const lookup=ref('');const preview=ref('');
const rights=ref<SourceRights>({origin_kind:'OWNED',license:'',source_label:'',allowed_uses:[]});const mediaType=ref<AssetUploadMetadata['declared_type']>('text/plain');const purpose=ref<AssetUploadMetadata['purpose']>('KNOWLEDGE');const pendingKey=ref('');const pendingUpload=ref<{metadata:AssetUploadMetadata;file:File;key:string}>();
async function refresh(){try{caps.value=await s.client.call('getCreatorCapabilities',{query:{product_id:s.productId}});const list:Release[]=[];let cursor:string|undefined;const seen=new Set<string>();do{const page=await s.client.call('listContentReleases',{query:{product_id:s.productId,...(cursor?{cursor}:{})}});list.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw Error('分页未前进');if(cursor)seen.add(cursor)}while(cursor);releases.value=list;error.value=undefined}catch(e){error.value=e}}
// Keep the first upload's metadata, file and key together until success; retries use that captured upload rather than newer local selections. Upload persists an asset independently of saving the draft.
async function upload(){try{if(!file.value||!caps.value)throw Error('请选择文件并取得当前上传能力');if(BigInt(file.value.size)>BigInt(caps.value.upload_max_bytes))throw Error('文件超过当前上传上限');const bytes=await file.value.arrayBuffer();const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');pendingKey.value||=crypto.randomUUID();pendingUpload.value??={metadata:JSON.parse(JSON.stringify({product_id:s.productId,purpose:purpose.value,declared_type:mediaType.value,name:file.value.name,expected_size:String(file.value.size),expected_sha256:hash,rights:rights.value,audience_policy:'PRODUCT_EDITORS'})),file:file.value,key:pendingKey.value};record.value=await s.client.upload(pendingUpload.value.metadata,pendingUpload.value.file,pendingUpload.value.key);pendingKey.value='';pendingUpload.value=undefined;error.value=undefined}catch(e){error.value=e}}
// Asset metadata is not the body: fetch authorized bytes separately, verify the hash and decode only supported text for preview. Preset adoption is a separate local-draft operation; preview does not map uploaded text into a NOTE.
async function read(){try{record.value=await s.client.call('getContentAsset',{path:{asset_id:lookup.value},query:{product_id:s.productId}});preview.value='';error.value=undefined}catch(e){error.value=e}}
async function textPreview(){try{if(!record.value||!['text/plain','text/markdown'].includes(record.value.media_type))throw Error('此处只预览文本，不执行上传文件');const bytes=await s.client.readAsset(record.value.asset_id,s.productId,record.value.size_bytes);const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes as Uint8Array<ArrayBuffer>))].map(b=>b.toString(16).padStart(2,'0')).join('');if(hash!==record.value.sha256)throw Error('文件校验不符');preview.value=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch(e){error.value=e}}
async function adopt(release:Release,objectId:string){try{if(!s.editable)throw Error('先在世界编辑中打开目标草稿');s.editable=await adoptPreset(s.editable,release,objectId,crypto.randomUUID());s.selectedId=s.editable.objects.at(-1)!.object_id;error.value=undefined}catch(e){error.value=e}}
onMounted(refresh);
</script>
<template><div class="page-heading"><div><p class="eyebrow">可复用的创作材料</p><h1>内容与资源</h1><p>文件上传独立持久保存；取消草稿不会删除已上传的文件。</p></div><button @click="refresh">刷新</button></div><FieldErrors :error="error"/><div class="two-columns"><section class="panel"><h2>上传文件</h2><p class="muted">上限 {{caps?.upload_max_bytes??'尚未取得'}} 字节。PDF / DOCX 可上传，自动提炼由后续 Task9 接通。</p><label>文件<input type="file" accept=".txt,.md,.png,.jpg,.jpeg,.pdf,.docx" @change="file=($event.target as HTMLInputElement).files?.[0]"/></label><label>文件类型<select v-model="mediaType"><option v-for="type in ['text/plain','text/markdown','image/png','image/jpeg','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']" :key="type">{{type}}</option></select></label><label>用途<select v-model="purpose"><option value="KNOWLEDGE">知识</option><option value="MEDIA">表现资源</option></select></label><SchemaField field="rights" path="/upload/rights" :schema="schemas.SourceRights" :model-value="rights" @update:model-value="rights=$event as SourceRights"/><button class="primary" @click="upload">{{pendingKey?'用原键重试上传':'上传文件'}}</button></section><section class="panel"><h2>已有资产</h2><form @submit.prevent="read"><label>资产标识<input v-model="lookup" required></label><button>读取当前状态</button></form><template v-if="record"><h3>{{record.name}}</h3><dl><dt>状态</dt><dd>{{record.state}}</dd><dt>资产</dt><dd>{{record.asset_id}}</dd><dt>大小</dt><dd>{{record.size_bytes}} 字节</dd><dt>SHA-256</dt><dd class="break">{{record.sha256}}</dd></dl><button :disabled="record.state!=='READY'" @click="textPreview">读取有权文本</button><pre v-if="preview" class="preview">{{preview}}</pre><template v-if="preview"><button disabled aria-describedby="note-mapping-unavailable">采用到当前 NOTE 草稿（尚未接通）</button><p id="note-mapping-unavailable">Task9 来源、受众与许可安全映射尚未接通；当前仅提供有权文本与校验预览，不能自动采用为笔记。</p></template></template></section></div><section class="panel"><h2>已发布内容</h2><p class="muted">以下为当前有权读取的不可变版本；本地采用与运行实例互相独立。</p><ul><li class="break" v-for="release in releases" :key="release.release_id">{{release.input.name}} · {{release.release_id}} · 修订 {{release.draft_revision}}<ul><li v-for="object in release.input.objects" :key="object.object_id">{{object.name}} · {{object.kind}} <button class="quiet" :disabled="!s.editable" @click="adopt(release,object.object_id)">采用到当前本地草稿</button></li></ul></li></ul></section><PackagePreview :releases="releases"/><section class="panel future"><h2>文档自动提炼与内容包搬迁</h2><p>本地匹配预览与实际导入分别处理。持久导入、导出分享和文档自动提炼仍待后续接通。</p></section></template>
